const fs = require('fs');

const rows = fs.readFileSync('reports/overnight-raw-evidence-20260626.jsonl', 'utf8')
  .trim()
  .split(/\r?\n/)
  .filter(Boolean)
  .map(JSON.parse);
const byId = new Map(rows.map((r) => [r.raw_id, r]));
const esc = (v) => `"${String(v ?? '').replace(/"/g, '""').replace(/\r?\n/g, ' ')}"`;
const csv = (file, arr, cols) => fs.writeFileSync(file, [cols.join(','), ...arr.map((o) => cols.map((c) => esc(o[c])).join(','))].join('\n'), 'utf8');
const pipeSummary = (ids) => {
  const rs = ids.map((id) => byId.get(id)).filter(Boolean);
  const has = (p) => rs.some(p);
  const all = (p) => rs.length > 0 && rs.every(p);
  const decisions = [...new Set(rs.map((r) => r.final_decision || r.decision || r.single_message_rejection_reason).filter(Boolean))].join('; ');
  const reasons = [...new Set(rs.map((r) => r.single_message_rejection_reason || r.run_error || r.llm_skip_reason).filter(Boolean))].join('; ');
  let stage = 'raw';
  if (all((r) => r.intake_status)) stage = 'intake';
  if (all((r) => r.queue_status)) stage = 'queue';
  if (all((r) => r.batch_id)) stage = 'batch';
  if (all((r) => r.run_id)) stage = 'run';
  if (all((r) => r.replay_run_message_id)) stage = 'replay';
  if (has((r) => r.embedding_id)) stage = 'embedding';
  if (has((r) => String(r.final_decision || '').includes('CANDIDATE'))) stage = 'candidate';
  if (has((r) => (r.provider_calls || 0) > 0)) stage = 'llm_judge';
  if (has((r) => r.knowledge_item_id || r.run_material_count > 0)) stage = 'material';
  const material = [...new Set(rs.flatMap((r) => [r.knowledge_item_id, ...(r.run_materials || []).map((m) => m.id)].filter(Boolean)))].join(';');
  return { stage, decisions, reasons, material };
};

