function mdTable(arr, cols) {
  return ['| ' + cols.map((c) => c.h).join(' | ') + ' |', '| ' + cols.map(() => '---').join(' | ') + ' |', ...arr.map((o) => '| ' + cols.map((c) => String(c.v(o) ?? '').replace(/\|/g, '/').replace(/\n/g, '<br>')).join(' | ') + ' |')].join('\n');
}

